namespace PinyinData {

bool isHan(ushort codePoint)
{
    return codePoint >= 0x4E00u && codePoint <= 0x9FA5u;
}

QStringList readings(ushort codePoint)
{
    QStringList result;
    if (!isHan(codePoint))
        return result;
    const int offset = codePoint - 0x4E00;
    const unsigned short primary = kPrimary[offset];
    if (primary == 0 || primary > kSyllableCount)
        return result;
    result.append(QString::fromLatin1(kSyllables[primary - 1]));

    const size_t altCount = sizeof(kAlternates) / sizeof(kAlternates[0]);
    const AltEntry *begin = kAlternates;
    const AltEntry *end = kAlternates + altCount;
    const AltEntry *it = std::lower_bound(
        begin, end, static_cast<unsigned short>(offset),
        [](const AltEntry &entry, unsigned short key) { return entry.offset < key; });
    for (; it != end && it->offset == offset; ++it) {
        if (it->syllable > 0 && it->syllable <= kSyllableCount)
            result.append(QString::fromLatin1(kSyllables[it->syllable - 1]));
    }
    return result;
}

} // namespace PinyinData
